120→    use tempfile::TempDir;
121→
122→    #[test]
123→    fn local_loader_empty_without_templates() {
124→        let temp = TempDir::new().unwrap();
125→        let loader = LocalLoader::new(Some(temp.path())).unwrap();
126→        assert!(loader.template_names().is_empty());
127→    }
128→
129→    #[test]
130→    fn local_loader_finds_project_templates() {
131→        let temp = TempDir::new().unwrap();
132→        let templates_dir = temp.path().join(".bivvy").join("templates").join("steps");
133→        fs::create_dir_all(&templates_dir).unwrap();
134→
135→        let template_yaml = r#"
136→name: custom
137→description: "A custom template"
138→category: custom
