mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn user_templates_dir_uses_xdg_data_dir() {
        let dir = LocalLoader::user_templates_dir();

        if let (Some(dir), Some(data_dir)) = (dir, dirs::data_dir()) {
            assert!(
                dir.starts_with(data_dir.join("bivvy")),
                "user_templates_dir should be under XDG data dir ({:?}/bivvy), got: {:?}",
                data_dir,
                dir
            );
        }
    }

    #[test]
    fn local_loader_empty_without_templates() {
        let temp = TempDir::new().unwrap();
        let loader = LocalLoader::new(Some(temp.path())).unwrap();
        assert!(loader.template_names().is_empty());
    }

    #[test]
    fn local_loader_finds_project_templates() {
        let temp = TempDir::new().unwrap();
        let templates_dir = temp.path().join(".bivvy").join("templates").join("steps");
        fs::create_dir_all(&templates_dir).unwrap();

        let template_yaml = r#"
name: custom
description: "A custom template"
category: custom
step:
  command: "echo custom"
"#;
        fs::write(templates_dir.join("custom.yml"), template_yaml).unwrap();

